parts.css:
/* 清透玻璃：可选聊天预设，引用无竖线。 */
.sully-chat-root { background-color:#536c63 !important; background-image:var(--sully-clear-glass-image, radial-gradient(ellipse at 18% 18%,#d7ded6 0,transparent 42%),linear-gradient(135deg,#99a69d,#536c63 58%,#bac7ba)) !important; background-size:cover !important; background-position:center !important; }
.sully-chat-header,.sully-chat-inputbar { background:rgba(230,239,230,.18) !important;backdrop-filter:blur(10px) !important;-webkit-backdrop-filter:blur(10px) !important;border-color:#ffffff50 !important;box-shadow:none !important; }
.sully-chat-message-content {max-width:70% !important;min-width:0 !important;}
.sully-bubble-user,.sully-bubble-ai {border-radius:20px !important;padding:6px 10px !important;border:.5px solid rgba(255,255,255,.5) !important;backdrop-filter:blur(10px) !important;-webkit-backdrop-filter:blur(10px) !important;box-shadow:0 2px 8px rgba(0,0,0,.1) !important;background-image:none !important;opacity:1 !important;}
.sully-bubble-user {background:rgba(255,255,255,.3) !important;color:#000 !important;}
.sully-bubble-ai {background:rgba(0,0,0,.2) !important;color:#fff !important;}
.sully-bubble-user > .select-text {color:#000 !important;}.sully-bubble-ai > .select-text {color:#fff !important;}
.sully-chat-reply-quote {border:0 !important;border-left:0 !important;border-radius:12px !important;padding:8px 10px !important;margin-bottom:8px !important;background:rgba(255,255,255,.2) !important;opacity:1 !important;backdrop-filter:blur(8px) !important;-webkit-backdrop-filter:blur(8px) !important;}
.sully-chat-reply-quote::before,.sully-chat-reply-quote::after {display:none !important;}
.sully-chat-reply-quote span {white-space:normal !important;overflow-wrap:anywhere !important;font-style:normal !important;}
.sully-chat-translation {font-size:14px !important;line-height:1.7 !important;border-color:currentColor !important;}
@media(max-width:360px){.sully-chat-message-content{max-width:73% !important;}}
@media(prefers-reduced-transparency:reduce){.sully-bubble-user{background:#e9eeea !important}.sully-bubble-ai{background:#40584f !important}}

.sully-chat-input-wrap{background:rgba(255,255,255,.2) !important;border:.5px solid #ffffff80 !important;border-radius:28px !important;backdrop-filter:blur(10px) !important;-webkit-backdrop-filter:blur(10px) !important;}
.sully-chat-input-wrap textarea,.sully-chat-composer textarea{background:transparent !important;color:#203b2c !important;}
